CREATE TABLE IF NOT EXISTS library_page_structural_classifications_v2 (
 classification_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source_run_id TEXT NOT NULL, page_anchor_id UUID NOT NULL REFERENCES library_page_anchors_v2(page_anchor_id), content_node_id UUID REFERENCES library_content_nodes_v2(content_node_id), pdf_page INTEGER NOT NULL, printed_page INTEGER, document_part TEXT NOT NULL, structural_status TEXT NOT NULL, lesson_number INTEGER, section_number INTEGER, confidence NUMERIC NOT NULL, evidence_origin JSONB NOT NULL, evidence_text JSONB NOT NULL, detector_version TEXT NOT NULL, classification_action TEXT NOT NULL, review_status TEXT NOT NULL, rationale TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(source_run_id,page_anchor_id));
CREATE OR REPLACE VIEW library_investigative_nodes_structural_v2 AS
SELECT n.content_node_id,n.content_unit_id,n.node_role,n.content_type,n.authority_level,n.literal_text,n.normalized_text,n.page_anchor_id,n.source_run_id AS page_first_source_run_id,n.metadata_json,n.link_status,n.review_status,
 c.source_run_id AS detector_run_id,c.document_part,c.structural_status,c.lesson_number,c.section_number,c.confidence AS structural_confidence,c.evidence_origin,c.evidence_text,c.classification_action
FROM library_content_nodes_v2 n LEFT JOIN library_page_structural_classifications_v2 c ON c.content_node_id=n.content_node_id;
